include "globals.mzn";

% Number of countries
int: num_countries = 6;

% Adjacency list
array[1..num_countries] of set of int: adjacency =
    [ {3, 1},
      {3, 6},
      {3, 4},
      {6, 4},
      {6, 1},
      {1, 5} ];

% Decision variables: color of each country
array[1..num_countries] of var 1..num_countries: colors;

% Constraints: two neighbouring countries cannot have the same color
constraint forall(i in 1..num_countries) (
    forall(j in adjacency[i]) (colors[i] != colors[j])
);

% Objective: minimize the number of colors used
solve minimize max(colors);

% Output the colors assigned to each country
output [
    "{",
    "\"colors\": [",
    join(", ", [show(colors[i]) | i in 1..num_countries]),
    "]",
    "}"
];
```

