include "globals.mzn";

% Number of cows
int: num_cows = 25;

% Number of sons
int: num_sons = 5;

% Milk production per cow
array[1..num_cows] of int: milk_production = [i | i in 1..num_cows];

% Number of cows per son
array[1..num_sons] of int: cows_per_son = [7, 6, 5, 4, 3];

% Decision variable: assignment of cows to sons
array[1..num_cows] of var 0..num_sons-1: cow_assignments;

% Constraint: each son gets the correct number of cows
constraint forall(i in 1..num_sons) (
  sum([cow_assignments[j] == i-1 | j in 1..num_cows]) == cows_per_son[i]
);

% Constraint: total milk production is the same for each son
array[1..num_sons] of var int: total_milk;
constraint forall(i in 1..num_sons) (
  total_milk[i] == sum([milk_production[j] | j in 1..num_cows where cow_assignments[j] == i-1])
);
constraint forall(i in 1..num_sons-1) (
  total_milk[i] == total_milk[i+1]
);

% Solve
solve satisfy;

% Print solution
output [
  "{",
  "\"cow_assignments\": [",
  join(", ", [show(cow_assignments[i]) | i in 1..num_cows]),
  "]",
  "}"
];
```

