% Define the number of gates
var int: num_gates = 5;

% Define the number of apples before each gate
var int: apples_before_gate = [var int: i | i in 1..num_gates+1];

% Constraints: the boy bribes each guard with half of his apples, plus one
constraint forall(i in 1..num_gates) (
  apples_before_gate[i+1] = (apples_before_gate[i] - (apples_before_gate[i] div 2 + 1))
);

% The boy has no apples left after the last gate
constraint apples_before_gate[num_gates+1] = 0;

% Find the smallest number of apples that satisfies the constraints
solve minimize apples_before_gate[1];

output [
  "[",
  join(", ", [show(apples_before_gate[i]) | i in 1..num_gates+1]),
  "]"
];
```

