% Input data
int: num_people = 8;
array[1..num_people] of set of int: compatible = [
    {2, 3},
    {1, 6},
    {1, 4, 7},
    {2},
    {2},
    {5},
    {8},
    {3}
];

% Decision Variables
array[1..num_people, 1..num_people] of var bool: transplants;

% Constraints
constraint forall(i in 1..num_people) (
    sum(j in 1..num_people) (bool2int(transplants[i, j])) <= 1
);
constraint forall(j in 1..num_people) (
    sum(i in 1..num_people) (bool2int(transplants[i, j])) <= 1
);
constraint forall(i in 1..num_people, j in 1..num_people) (
    transplants[i, j] -> j in compatible[i]
);
constraint forall(i in 1..num_people) (
    sum(j in 1..num_people) (bool2int(transplants[i, j])) =
    sum(j in 1..num_people) (bool2int(transplants[j, i]))
);

% Objective function
solve maximize sum(i in 1..num_people, j in 1..num_people) (bool2int(transplants[i, j]));

% Output
output [
    "{\n",
    "    \"transplants\": [\n",
    join(",\n", [
        "        [" ++ join(", ", [show(bool2int(transplants[i, j])) | j in 1..num_people]) ++ "]"
        | i in 1..num_people
    ]),
    "    ]\n",
    "}"
];
