% Size of the magic square
int: n = 4;

% The magic constant (sum of each row, column and diagonal)
int: magic_constant = n * (n * n + 1) div 2;

% Decision variables: the numbers in the magic square
array[1..n, 1..n] of var 1..n*n: square;

% Each number appears exactly once
constraint alldifferent([square[i, j] | i in 1..n, j in 1..n]);

% Each row sums up to the magic constant
constraint forall(i in 1..n) (sum(j in 1..n) (square[i, j]) = magic_constant);

% Each column sums up to the magic constant
constraint forall(j in 1..n) (sum(i in 1..n) (square[i, j]) = magic_constant);

% The main diagonal sums up to the magic constant
constraint sum(i in 1..n) (square[i, i]) = magic_constant;

% The other diagonal sums up to the magic constant
constraint sum(i in 1..n) (square[i, n-i+1]) = magic_constant;

solve satisfy;

output [
    "{\n",
    "    \"square\": [\n",
    join(",\n", [
        "        [" ++ join(", ", [show(square[i, j]) | j in 1..n]) ++ "]"
        | i in 1..n
    ]),
    "    ]\n",
    "}"
];
