var bool: crackitt;
var bool: dodgy;
var bool: edgy;
var bool: fingers;

% Constraints
% At least 4 innocent
constraint 4 <= 6 - (artie + bill + crackitt + dodgy + edgy + fingers);

% Artie says it wasn't him, so if he's guilty, he's lying
constraint not artie -> not artie;

% Bill says Crackitt was in it, so if Bill is guilty, Crackitt must be guilty
constraint bill -> crackitt;

% Crackitt says he wasn't in it, so if he's guilty, he's lying
constraint not crackitt -> not crackitt;

% Dodgy says if Crackitt did it, Bill did it with him
constraint (crackitt -> bill) /\ (not crackitt -> (not bill));

% Edgy says nobody did it alone
constraint edgy -> (artie + bill + crackitt + dodgy + fingers >= 2);

% Fingers says it was Artie and Dodgy together
constraint fingers -> (artie /\ dodgy);

% If someone is guilty, they are lying
constraint (artie -> (bill \/ crackitt \/ dodgy \/ edgy \/ fingers)) /\
               (bill -> (not crackitt)) /\
               (crackitt -> (not (not crackitt))) /\
               (dodgy -> (not ((crackitt -> bill) /\ (not crackitt -> (not bill))))) /\
               (edgy -> (not (edgy -> (artie + bill + crackitt + dodgy + fingers >= 2)))) /\
               (fingers -> (not (artie /\ dodgy)));

% Solve
solve satisfy;

% Output
output [
