% Input data
array[1..3] of array[1..3] of tuple(int, int): jobs_data = [
    [(0, 3), (1, 2), (2, 2)],
    [(0, 2), (2, 1), (1, 4)],
    [(1, 4), (2, 3)]
];

% Number of jobs
int: num_jobs = length(jobs_data);

% Number of machines
set of int: machines = {0, 1, 2};

% Number of tasks for each job
array[1..num_jobs] of int: num_tasks = [length(jobs_data[j]) | j in 1..num_jobs];

% Maximum number of tasks
int: max_tasks = max(num_tasks);

% Task start times
array[1..num_jobs, 1..max_tasks] of var 0..100: task_start;

% Task durations
array[1..num_jobs, 1..max_tasks] of int: task_duration =
    [if i <= num_tasks[j] then jobs_data[j][i].2 else 0 | j in 1..num_jobs, i in 1..max_tasks];

% Machine tasks
array[1..3] of array[1..sum(num_tasks)] of var 0..1: machine_tasks;

% Machine task start times
array[1..3] of array[1..sum(num_tasks)] of var 0..100: machine_task_start;

% Machine task durations
array[1..3] of array[1..sum(num_tasks)] of int: machine_task_duration;

% Number of tasks for each machine
array[1..3] of int: num_machine_tasks = [sum([if jobs_data[j][i].1 = m then 1 else 0 | j in 1..num_jobs, i in 1..num_tasks[j]]) | m in machines];

% Initialize machine tasks
int: task_index = 1;
for m in machines do
    for j in 1..num_jobs do
        for i in 1..num_tasks[j] do
            if jobs_data[j][i].1 = m then
                machine_tasks[m][task_index] = 1;
                machine_task_start[m][task_index] = task_start[j, i];
                machine_task_duration[m][task_index] = task_duration[j, i];
                task_index += 1;
            endif;
        endfor;
    endfor;
endfor;

% Constraints
% No task for a job can be started until the previous task for that job is completed
for j in 1..num_jobs do
    for i in 2..num_tasks[j] do
        constraint task_start[j, i] >= task_start[j, i-1] + task_duration[j, i-1];
    endfor;
endfor;

% A machine can only work on one task at a time
for m in machines do
    for i in 1..num_machine_tasks[m] do
        for j in i+1..num_machine_tasks[m] do
            constraint machine_task_start[m][i] + machine_task_duration[m][i] <= machine_task_start[m][j] \/
                           machine_task_start[m][j] + machine_task_duration[m][j] <= machine_task_start[m][i];
        endfor;
    endfor;
endfor;

% Objective function: minimize makespan
var 0..100: makespan;
constraint makespan >= task_start[j, num_tasks[j]] + task_duration[j, num_tasks[j]] for j in 1..num_jobs;

solve minimize makespan;

output [
    "{",
    "\"makespan\": ", show(makespan),
    "}"
];
