int: num_items = 4;
array[1..num_items] of int: widths = [3, 4, 2, 1];
array[1..num_items] of int: heights = [2, 3, 1, 4];

% Decision variables
array[1..num_items] of var int: pos_x;
array[1..num_items] of var int: pos_y;
var int: total_x;
var int: total_y;

