include "globals.mzn";

% Number of cities
int: n = 12;

% Locations of cities
array[1..n] of int: x = [288, 288, 270, 256, 256, 246, 236, 228, 228, 220, 212, 204];
array[1..n] of int: y = [149, 129, 133, 141, 163, 157, 169, 169, 148, 164, 172, 159];

% Distance between each pair of cities
function int: distance(int: i, int: j) =
    sqrt((x[i] - x[j]) ^ 2 + (y[i] - y[j]) ^ 2);

% Decision variable: next city to visit
array[1..n] of var 1..n: next;

% Constraints
constraint alldifferent(next);
constraint forall(i in 1..n) (next[i] != i);
constraint forall(i in 1..n) (next[next[i]] != i);
constraint circuit(next);

% Objective function: minimize total travel distance
var int: travel_distance = sum(i in 1..n) (distance(i, next[i])) + distance(next[n], 1);

% Solve
solve minimize travel_distance;

% Output
