% Total number of cars
total_cars = sum(demand);

% Decision variable: sequence of car types
array[1..total_cars] of var 0..num_car_types-1: sequence;

% Constraints: each car type is produced the required number of times
constraint forall(i in 1..num_car_types) (
    sum([sequence[j] == i | j in 1..total_cars]) == demand[i]
);

% Constraints: each property is not bunched together
constraint forall(p in 1..num_properties) (
    forall(i in 1..total_cars-per_slots[p]+1) (
        sum([requires[sequence[j], p] | j in i..i+per_slots[p]-1]) <= at_most[p]
    )
);

% Solve the model
solve satisfy;

% Print the solution
output [
    "{",
    "\"sequence\": [",
    join(", ", [show(sequence[i]) | i in 1..total_cars]),
    "]",
    "}"
];
