    [0, 5],
    [0, 4],
    [1, 3],
    [0, 2]
];

% Decision Variables
array[1..rows, 1..cols] of var bool: board;

% Constraints
constraint forall(i in 1..rows) (
    let {
        array[1..row_rule_len] of var int: rule = row_rules[i];
        array[1..cols] of var int: block_lengths;
        array[1..cols] of var bool: is_block_start;
    } in (
        block_lengths := [if j = 1 then 0 else if board[i, j] and not board[i, j-1] then 1 else block_lengths[j-1] + 1 | j in 1..cols];
        is_block_start := [board[i, j] and (j = 1 or not board[i, j-1]) | j in 1..cols];
        sum([if is_block_start[j] then block_lengths[j] else 0 | j in 1..cols]) = sum([if k = 1 and rule[k] > 0 then rule[k] else if k > 1 and rule[k] > 0 then rule[k] else 0 | k in 1..row_rule_len])
    )
);

constraint forall(j in 1..cols) (
    let {
        array[1..col_rule_len] of var int: rule = col_rules[j];
        array[1..rows] of var int: block_lengths;
        array[1..rows] of var bool: is_block_start;
    } in (
        block_lengths := [if i = 1 then 0 else if board[i, j] and not board[i-1, j] then 1 else block_lengths[i-1] + 1 | i in 1..rows];
