        sum([if is_block_start[i] then block_lengths[i] else 0 | i in 1..rows]) = sum([if k = 1 and rule[k] > 0 then rule[k] else if k > 1 and rule[k] > 0 then rule[k] else 0 | k in 1..col_rule_len])
    )
);

% Objective function (satisfy)
solve satisfy;

% Output
output [
    "{\n",
    "    \"board\": [\n",
    join(",\n", [
        "        [" ++ join(", ", [if board[i, j] then "1" else "0" | j in 1..cols]) ++ "]"
        | i in 1..rows
    ]),
    "\n    ]\n",
    "}"
];
