include "globals.mzn";

% Input data
n_boats = 5;
n_periods = 4;
capacity = [6, 8, 12, 12, 12];
crew_size = [2, 2, 2, 2, 4];

% Decision Variables
array[1..n_boats] of var bool: is_host; % Whether a boat is a host
array[1..n_boats, 1..n_periods] of var 1..n_boats: visits; % Visit schedule

% Constraints
constraint forall(b in 1..n_boats) (
    forall(p in 1..n_periods) (
        (is_host[b] -> visits[b, p] = b) /\
        (not is_host[b] -> visits[b, p] in 1..n_boats)
    )
);

constraint forall(h in 1..n_boats) (
    is_host[h] -> 
    forall(p in 1..n_periods) (
        sum([crew_size[b] | b in 1..n_boats where visits[b, p] = h]) <= capacity[h]
    )
);

constraint forall(b in 1..n_boats where not is_host[b]) (
    forall(h1, h2 in 1..n_boats where h1 < h2) (
        is_host[h1] /\ is_host[h2] -> 
        visits[b, 1] != visits[b, 2] /\ 
        visits[b, 1] != visits[b, 3] /\ 
        visits[b, 1] != visits[b, 4] /\ 
        visits[b, 2] != visits[b, 3] /\ 
        visits[b, 2] != visits[b, 4] /\ 
        visits[b, 3] != visits[b, 4]
    )
);

constraint forall(b1, b2 in 1..n_boats where b1 < b2) (
    not is_host[b1] /\ not is_host[b2] -> 
    forall(p in 1..n_periods) (
        visits[b1, p] != visits[b2, p]
    )
);

% Objective function
solve minimize sum(is_host);

% Output
output [
    "{",
    "\"visits\": [",
    join(", ", [
        "[" ++ join(", ", [show(visits[b, p]) | p in 1..n_periods]) ++ "]"
        | b in 1..n_boats
    ]),
    "],",
    "\"is_host\": [",
    join(", ", [show(is_host[b]) | b in 1..n_boats]),
    "]",
    "}"
];
```

