include "globals.mzn";

% Input data
int: n = 8; % Number of words to find
int: length = 8; % Length of each word
set of int: alphabet = {1, 2, 3, 4}; % Alphabet: 1=A, 2=C, 3=G, 4=T

% Mapping from alphabet to Watson-Crick complement
array[alphabet] of int: complement = [4, 3, 2, 1];

% Decision variables
array[1..n, 1..length] of var alphabet: words;

% Constraints
constraint forall(i in 1..n) (
    sum(j in 1..length) (words[i, j] in {2, 3}) = 4 % Each word has 4 symbols from {C, G}
);

constraint forall(i, j in 1..n where i < j) (
    sum(k in 1..length) (words[i, k] != words[j, k]) >= 4 % Each pair of distinct words differ in at least 4 positions
);

constraint forall(i, j in 1..n) (
    sum(k in 1..length) (complement[words[j, k]] != words[i, length - k + 1]) >= 4 % Each pair of words x and y are such that x^R and y^C differ in at least 4 positions
);

% Solve
solve satisfy;

% Output
output [
    "{\n",
    "    \"words\": [\n",
    join(",\n", [
        "        ["
        ++ join(", ", [
            show(if words[i, j] = 1 then "A" elif words[i, j] = 2 then "C" elif words[i, j] = 3 then "G" else "T")
            | j in 1..length
        ])
        ++ "]"
        | i in 1..n
    ]),
    "\n    ]\n",
    "}"
];
```

