include "globals.mzn";

% Number of vertices
int: N = 10;

% Decision variables: adjacency matrix
array[1..N, 1..N] of var bool: adj;

% Constraints: simple graph
constraint forall(i in 1..N) (not adj[i, i]); % no loops
constraint forall(i in 1..N, j in i+1..N) (adj[i, j] -> adj[j, i]); % undirected edges

% Constraints: diamond-free
constraint forall(a in 1..N, b in a+1..N, c in b+1..N, d in c+1..N) (
  adj[a, b] + adj[a, c] + adj[a, d] + adj[b, c] + adj[b, d] + adj[c, d] <= 4
);

% Constraints: degree sequence
array[1..N] of var int: degree;
constraint forall(i in 1..N) (
  degree[i] = sum(j in 1..N) (adj[i, j])
);
constraint forall(i in 1..N) (degree[i] > 0); % no isolated vertices
constraint forall(i in 1..N) (degree[i] mod 3 = 0); % degree modulo 3
constraint sum(i in 1..N) (degree[i]) mod 12 = 0; % sum of degrees modulo 12

% Constraints: non-increasing degree sequence
constraint forall(i in 1..N-1) (degree[i] >= degree[i+1]);

% Solve
solve satisfy;

% Output
output [
  "{\n",
  "  \"matrix\": [\n",
  join(",\n", [
    "    ["
    ++ join(", ", [if adj[i, j] then "1" else "0" | j in 1..N])
    ++ "]"
    | i in 1..N
  ]),
  "  ]\n",
  "}"
];
```

