constraint forall(i in 1..num_dice, j in 1..num_sides) (die[i, j] <= num_sides);

% Constraints: Rock(1) crushes Scissors(3)
constraint forall(i in 1..num_sides) (die[1, i] > die[3, i]);

% Constraints: Rock(1) crushes Lizard(4)
constraint forall(i in 1..num_sides) (die[1, i] > die[4, i]);

% Constraints: Paper(2) covers Rock(1)
constraint forall(i in 1..num_sides) (die[2, i] > die[1, i]);

% Constraints: Paper(2) disproves Spock(5)
constraint forall(i in 1..num_sides) (die[2, i] > die[5, i]);

% Constraints: Scissors(3) cuts Paper(2)
constraint forall(i in 1..num_sides) (die[3, i] > die[2, i]);

% Constraints: Scissors(3) decapitate Lizard(4)
constraint forall(i in 1..num_sides) (die[3, i] > die[4, i]);

% Constraints: Lizard(4) eats Paper(2)
constraint forall(i in 1..num_sides) (die[4, i] > die[2, i]);

% Constraints: Lizard(4) poisons Spock(5)
constraint forall(i in 1..num_sides) (die[4, i] > die[5, i]);

% Constraints: Spock(5) vaporizes Rock(1)
constraint forall(i in 1..num_sides) (die[5, i] > die[1, i]);

% Constraints: Spock(5) smashes Scissors(3)
constraint forall(i in 1..num_sides) (die[5, i] > die[3, i]);

% Solve the model
solve satisfy;

% Output the solution
output [
    "{\n",
