  [ connections[i, j] * abs(position[i] - position[j]) |
    i in 1..num_devices, j in i+1..num_devices
  ]
);

% Solve the model
solve minimize final_sum;

% Print the solution
output [
  "{",
  "\"final_sum\": ", show(final_sum),
  "}"
