% Input data
int: num_moves = 3;
array[1..3] of int: init = [1, 0, 1];

% Decision Variables
array[1..num_moves, 1..3] of var int: steps;

% Constraints
constraint forall(i in 1..num_moves) (
    steps[i,1] + steps[i,2] + steps[i,3] == 1
);
constraint forall(i in 1..num_moves-1, j in 1..3) (
    steps[i,j] + steps[i+1,j] <= 1
);
constraint forall(j in 1..3) (
    init[j] + sum(i in 1..num_moves) (if steps[i,j] = 1 then 1 else -1 endif) in {0, 1}
);

% Objective function (optional)
solve satisfy;

% Output
output [
    "{",
    "\"steps\": [",
    join(",\n", [
        "[" ++ show(steps[i,1]) ++ ", " ++ show(steps[i,2]) ++ ", " ++ show(steps[i,3]) ++ "]"
        | i in 1..num_moves
    ]),
    "]",
    "}"
];
```

